// Google Sheets에서 가져온 데이터
const inputData = $input.all();

// 결과를 저장할 배열
const results = [];

// 각 항목을 처리
for (const item of inputData) {
  const data = item.json;

  // PC URL을 모바일 URL로 변경
  let mobileUrl = data.url || '';

  if (mobileUrl) {
    mobileUrl = mobileUrl
      .replace('blog.naver.com', 'm.blog.naver.com')
      .replace('m.m.blog.naver.com', 'm.blog.naver.com'); // 중복 방지
  }

  // 결과 객체 생성
  results.push({
    json: {
      row_number: data.row_number,
      ID: data.ID,
      original_url: data.url,
      mobile_url: mobileUrl,
      Status: data.Status,
      Voice: data.Voice,
      Voice_ID: data.Voice_ID,
      title: data.title,
      description: data.description,
      script: data.script,
      tags: data.tags,
      video_url: data.video_url
    }
  });
}

return results;

